window.STUDY_DATA.questions.push({"id":"img-net-01","module":"major","subject":"计算机网络基础","chapter":"ch-net-1","knowledgePoint":"OSI七层模型","type":"single","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"在OSI模型中，路由器工作在哪一层？<br><svg width='220' height='180' xmlns='http://www.w3.org／2000／svg'><rect width='220' height='180' fill='#fafafa'/><rect x='60' y='10' width='100' height='20' fill='#e3f2fd' stroke='#333'/><text x='75' y='24' font-size='10'>应用层</text><rect x='60' y='30' width='100' height='20' fill='#e3f2fd' stroke='#333'/><text x='75' y='44' font-size='10'>表示层</text><rect x='60' y='50' width='100' height='20' fill='#e3f2fd' stroke='#333'/><text x='75' y='64' font-size='10'>会话层</text><rect x='60' y='70' width='100' height='20' fill='#fff3e0' stroke='#333'/><text x='75' y='84' font-size='10'>传输层</text><rect x='60' y='90' width='100' height='20' fill='#ffe0b2' stroke='#333' stroke-width='2.5'/><text x='75' y='104' font-size='10' font-weight='bold'>网络层</text><rect x='60' y='110' width='100' height='20' fill='#e3f2fd' stroke='#333'/><text x='75' y='124' font-size='10'>数据链路层</text><rect x='60' y='130' width='100' height='20' fill='#e3f2fd' stroke='#333'/><text x='75' y='144' font-size='10'>物理层</text><text x='170' y='104' font-size='10'>← 路由器</text></svg>","options":["物理层","数据链路层","网络层","传输层"],"answer":"网络层","analysis":"【审题】路由器工作在 OSI 哪一层。考设备与层次的对应。【定律/公式】物理层：集线器/中继器；数据链路层：交换机/网桥（MAC）；网络层：路由器（IP）；传输层及以上：四层交换机/代理。转发决策依据的层次即\"工作层\"。【分步推导】① 选路需 IP 编址。② 排除物理层与链路层设备。③ 设备分层对照表。④ 路由器跨层封装但决策在第三层。【答案】网络层（选项 C）。【易错】当交换机；当物理层设备；与网关混；以为看 MAC。","tags":["带图","OSI"],"source":"带图题","score":5,"steps":["【秒懂考点】路由器工作在网络层（OSI 第三层），依据 IP 地址转发数据包","【第一步：按功能定位】路由器的核心任务是连接不同网络并在其间选路。选路需要 IP 地址，而 IP 地址属网络层编址，所以它在网络层工作","【第二步：排除干扰项】物理层设备是集线器、中继器、网线；数据链路层设备是交换机、网桥（依据 MAC 地址）；传输层设备是网关型设备或四层交换机。路由器对应网络层","【第三步：对照记忆表】集线器/中继器→物理层；交换机/网桥→数据链路层；路由器→网络层；四层交换机/代理→传输层及以上。这套对照几乎覆盖所有设备分层题","【第四步：路由器内部其实跨多层】它收包时要解物理层与链路层（拆掉以太网帧头），再按网络层 IP 头查路由表，出包时重新封装新的链路层帧头。但题问\"工作在哪一层\"指的是它做转发决策所依据的主要层次，即网络层","【答案】网络层（C）"],"pitfalls":["把路由器当链路层设备：那是交换机的层次","把路由器当物理层设备：它要做选路","与网关概念混：路由器常兼网关，但层次是网络层","以为路由器只看 MAC 转发: 它看 IP"]});

window.STUDY_DATA.questions.push({"id":"img-net-02","module":"major","subject":"计算机网络基础","chapter":"ch-net-3","knowledgePoint":"IP与子网","type":"single","typeLabel":"单选","difficulty":2,"difficultyLabel":"强化","stem":"图中主机A的IP为192.168.1.10／24，主机B的IP为192.168.2.20／24，二者能否直接通信？<br><svg width='240' height='120' xmlns='http://www.w3.org／2000／svg'><rect width='240' height='120' fill='#fafafa'/><rect x='20' y='40' width='50' height='40' fill='#e8f5e9' stroke='#333'/><text x='25' y='58' font-size='9'>主机A</text><text x='22' y='72' font-size='8'>192.168.1.10</text><line x1='70' y1='60' x2='100' y2='60' stroke='#333' stroke-width='2'/><rect x='100' y='45' width='40' height='30' fill='#fff9c4' stroke='#333'/><text x='105' y='63' font-size='9'>路由器</text><line x1='140' y1='60' x2='170' y2='60' stroke='#333' stroke-width='2'/><rect x='170' y='40' width='50' height='40' fill='#e8f5e9' stroke='#333'/><text x='175' y='58' font-size='9'>主机B</text><text x='172' y='72' font-size='8'>192.168.2.20</text></svg>","options":["能，同网段","不能，不同网段需经路由器转发","能，只要ping就通","不能，网线没插"],"answer":"不能，不同网段需经路由器转发","analysis":"【审题】判断两个 /24 地址能否直接通信。考网络地址计算与同网段判定。【定律/公式】网络地址 = IP 与掩码按位与；/24 掩码为 255.255.255.0；网络地址相同才是同网段；同网段用 ARP+MACK 直发，跨网段交网关。【分步推导】① A 网络地址 192.168.1.0、B 为 192.168.2.0。② 两者不同 → 跨网段。③ 图中路由器为拓扑提示。④ 排除三项干扰。【答案】不能，不同网段需经路由器转发（选项 B）。【易错】只看前缀相同；不按掩码计算；误判同网段；归因物理层。","tags":["带图","子网","跨网段"],"source":"带图题","score":6,"steps":["【秒懂考点】两台主机都是 /24 前缀，但一台在 192.168.1 网段、另一台在 192.168.2 网段，属不同网络，必须经路由器转发才能通信","【第一步：算出各自的网络地址】/24 表示前 24 位是网络位、后 8 位是主机位，掩码 255.255.255.0。A：192.168.1.10 与掩码按位与 → 192.168.1.0；B：192.168.2.20 与掩码按位与 → 192.168.2.0","【第二步：比较网络地址】192.168.1.0 与 192.168.2.0 不同，说明不在同一网段。同一网段通信靠 ARP 得到对方 MAC 直接发帧；跨网段则必须把包交给网关（路由器）","【第三步：图中已经给出答案线索】图中两主机之间画了路由器，这本身就是拓扑提示：它们被路由器隔开，属于两个不同的广播域","【第四步：排除干扰项】\"能，同网段\"错在网段判断；\"能，只要 ping 就通\"错在把工具当条件；\"不能，网线没插\"错在归因，图中是网段不同而非物理断连。【答案】不能，不同网段需经路由器转发（B）","【答案】不能，不同网段需经路由器转发（B）"],"pitfalls":["只看\"都是 192.168\"就判同网段：第三段不同即不同网段","忘记按掩码求网络地址","以为 /24 下 1.x 与 2.x 可直接通信","把不能通信归因于物理连接"]});

window.STUDY_DATA.questions.push({"id":"img-net-03","module":"major","subject":"计算机网络基础","chapter":"ch-net-3","knowledgePoint":"TCP三次握手","type":"single","typeLabel":"单选","difficulty":2,"difficultyLabel":"强化","stem":"TCP建立连接的正确顺序是？<br><svg width='260' height='140' xmlns='http://www.w3.org／2000／svg'><rect width='260' height='140' fill='#fafafa'/><text x='20' y='20' font-size='11'>客户端</text><text x='200' y='20' font-size='11'>服务器</text><line x1='40' y1='100' x2='40' y2='30' stroke='#333' stroke-width='2'/><line x1='210' y1='100' x2='210' y2='30' stroke='#333' stroke-width='2'/><line x1='40' y1='50' x2='200' y2='60' stroke='#2196f3' stroke-width='2'/><polygon points='200,60 190,55 190,65' fill='#2196f3'/><text x='80' y='48' font-size='9'>① SYN</text><line x1='210' y1='80' x2='50' y2='90' stroke='#4caf50' stroke-width='2'/><polygon points='50,90 60,85 60,95' fill='#4caf50'/><text x='80' y='88' font-size='9'>② SYN+ACK</text><line x1='40' y1='110' x2='200' y2='115' stroke='#ff9800' stroke-width='2'/><polygon points='200,115 190,110 190,120' fill='#ff9800'/><text x='80' y='113' font-size='9'>③ ACK</text></svg>","options":["SYN → ACK → SYN+ACK","SYN → SYN+ACK → ACK","SYN → FIN → ACK","ACK → SYN → SYN+ACK"],"answer":"SYN → SYN+ACK → ACK","analysis":"【审题】TCP 建立连接的三次握手顺序。考握手报文与次数必要性。【定律/公式】SYN(seq=x) → SYN+ACK(seq=y, ack=x+1) → ACK(ack=y+1)；两次不够因服务器无法确认客户端收到 SYN；断开为四次挥手。【分步推导】① 三步各自作用。② 为何必须三次。③ 排除三种错误顺序。④ 与四次挥手对照。【答案】SYN → SYN+ACK → ACK（选项 B）。【易错】误判两次够；拆包；与挥手混；主动方弄反。","tags":["带图","TCP","三次握手"],"source":"带图题","score":6,"steps":["【秒懂考点】TCP 建立连接是三次握手，顺序为：客户端发 SYN → 服务器回 SYN+ACK → 客户端回 ACK","【第一步：每一次在做什么】第一次：客户端发 SYN、带上自己的初始序号 seq=x，表示\"我想建连，我的起始号是 x\"；第二次：服务器回 SYN+ACK，既确认收到（ack=x+1），又带上自己的初始序号 seq=y；第三次：客户端回 ACK（ack=y+1），确认收到服务器的序号","【第二步：为什么必须三次而不是两次】两次握手无法让服务器确认\"客户端已收到我的 SYN\"。若第二次的包丢失，客户端不会回应，服务器却已认为连接建立，会白白占用资源等待数据。三次握手让双方都确认\"我能发、你能收、你能发、我能收\"","【第三步：排除干扰项】\"SYN → ACK → SYN+ACK\"把第二三次顺序颠倒，实际第二次必须同时带 SYN 与 ACK；\"SYN → FIN → ACK\"混入了断开连接的 FIN；\"ACK → SYN → SYN+ACK\"起始就错，主动方必须先发 SYN","【第四步：顺带记住断开过程】断开是四次挥手：FIN → ACK → FIN → ACK。因为 TCP 是全双工，两个方向要各自关闭，所以比建立多一次","【答案】SYN → SYN+ACK → ACK（B）"],"pitfalls":["以为两次握手就够：无法确认客户端收到服务器 SYN","把 SYN 与 ACK 拆成两次而非合并在第二包","与四次挥手混：建立 3 次、断开 4 次","搞错主动方：发起方先发 SYN"]});

window.STUDY_DATA.questions.push({"id":"img-net-04","module":"major","subject":"计算机网络基础","chapter":"ch-net-2","knowledgePoint":"网络设备","type":"single","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"图中设备Hub（集线器）工作在OSI哪一层？<br><svg width='220' height='100' xmlns='http://www.w3.org／2000／svg'><rect width='220' height='100' fill='#fafafa'/><rect x='80' y='30' width='60' height='40' fill='#ffebee' stroke='#333'/><text x='85' y='55' font-size='10'>Hub</text><line x1='30' y1='20' x2='80' y2='40' stroke='#333' stroke-width='1.5'/><line x1='30' y1='80' x2='80' y2='60' stroke='#333' stroke-width='1.5'/><line x1='140' y1='40' x2='190' y2='20' stroke='#333' stroke-width='1.5'/><line x1='140' y1='60' x2='190' y2='80' stroke='#333' stroke-width='1.5'/><text x='20' y='18' font-size='9'>PC1</text><text x='20' y='95' font-size='9'>PC2</text><text x='185' y='18' font-size='9'>PC3</text><text x='185' y='95' font-size='9'>PC4</text></svg>","options":["物理层","数据链路层","网络层","应用层"],"answer":"物理层","analysis":"【审题】Hub 工作在 OSI 哪一层。考共享式设备与交换式设备的层次差别。【定律/公式】Hub 物理层、广播式复制信号、单一冲突域、半双工共享带宽；交换机数据链路层、学习 MAC 表、按目的 MAC 定向转发、每端口独立冲突域。【分步推导】① Hub 的转发行为。② 为何止于物理层。③ 与交换机对照。④ 实际影响与判据。【答案】物理层（选项 A）。【易错】当链路层；与交换机混；冲突域误解；以为会选路。","tags":["带图","网络设备"],"source":"带图题","score":5,"steps":["【秒懂考点】集线器（Hub）工作在物理层，它只是把收到的信号放大后向所有端口广播，不认识 MAC 地址","【第一步：Hub 的行为】任一端口收到电信号，Hub 就向其余所有端口转发同一份信号。所有连接的设备共享同一个冲突域，同一时刻只能有一台发送，否则冲突","【第二步：为什么不可能是上层】它不解析帧头、不看 MAC、不看 IP，只做电气层面的信号复制，因此止于物理层。这与它\"共享带宽、半双工\"的特性一致","【第三步：与交换机对照】交换机是数据链路层设备，能学习 MAC 地址表并按目的 MAC 定向转发，每个端口是独立冲突域；Hub 做不到定向，只能广播","【第四步：实际影响】Hub 连接的设备越多，冲突概率越高、有效带宽越低。这也是 Hub 被交换机取代的原因。做题时抓住\"不认识地址、只复制信号\"就能立刻判定为物理层","【答案】物理层（A）"],"pitfalls":["把 Hub 当链路层设备：它不看 MAC","把 Hub 与交换机混：交换机才按 MAC 转发","以为 Hub 能隔离冲突域：所有端口同一冲突域","以为 Hub 会选路：完全不涉及 IP"]});

window.STUDY_DATA.questions.push({"id":"img-net-05","module":"major","subject":"计算机网络基础","chapter":"ch-net-4","knowledgePoint":"HTTP与DNS","type":"single","typeLabel":"单选","difficulty":2,"difficultyLabel":"强化","stem":"浏览器输入www.example.com后，第一步发生什么？<br><svg width='240' height='140' xmlns='http://www.w3.org／2000／svg'><rect width='240' height='140' fill='#fafafa'/><rect x='10' y='50' width='50' height='40' fill='#e3f2fd' stroke='#333'/><text x='15' y='73' font-size='9'>浏览器</text><rect x='95' y='50' width='50' height='40' fill='#fff3e0' stroke='#333'/><text x='100' y='73' font-size='9'>DNS</text><rect x='180' y='50' width='50' height='40' fill='#e8f5e9' stroke='#333'/><text x='185' y='73' font-size='9'>Web服务器</text><line x1='60' y1='65' x2='95' y2='65' stroke='#2196f3' stroke-width='2'/><polygon points='95,65 88,60 88,70' fill='#2196f3'/><text x='62' y='58' font-size='8'>①查IP</text><line x1='145' y1='75' x2='180' y2='75' stroke='#4caf50' stroke-width='2'/><polygon points='180,75 173,70 173,80' fill='#4caf50'/><text x='150' y='90' font-size='8'>②HTTP请求</text></svg>","options":["直接连接Web服务器","先向DNS查询域名对应的IP地址","直接ping Web服务器","先发TCP三次握手到80端口"],"answer":"先向DNS查询域名对应的IP地址","analysis":"【审题】输入域名后的第一步操作。考 DNS 与后续流程的先后顺序。【定律/公式】域名 → DNS 解析得 IP → TCP 三次握手 → HTTP 请求 → 响应 → 渲染；分级查询顺序：本地缓存/hosts → 本地 DNS → 根 → 顶级域 → 权威服务器。【分步推导】① 必须先有 IP 的原因。② 解析的递归路径。③ 拿到 IP 后的动作链。④ 排除三项错序。【答案】先向 DNS 查询域名对应的 IP 地址（选项 B）。【易错】握手前置；ping 混入；跳过解析；解析时机误解。","tags":["带图","DNS","HTTP"],"source":"带图题","score":6,"steps":["【秒懂考点】浏览器输入域名后第一步是域名解析：先向 DNS 查询该域名对应的 IP 地址","【第一步：为什么必须先解析】HTTP 通信最终要靠 IP 地址寻址，浏览器并不知道 www.example.com 的 IP。没有 IP 就无法建立 TCP 连接，更无法发请求","【第二步：解析的递归过程】先查本机 hosts 与本地 DNS 缓存 → 本地 DNS 服务器 → 根域名服务器 → 顶级域（com）服务器 → 权威域名服务器，逐级问到 A 记录后返回 IP","【第三步：拿到 IP 之后做什么】与服务器 80 端口做 TCP 三次握手 → 发 HTTP GET 请求 → 服务器返回响应 → 浏览器解析 HTML 并加载页面资源。所以 DNS 一定排在握手之前","【第四步：排除干扰项】\"直接连接 Web 服务器\"没有 IP 无法连；\"直接 ping\"同样需要 IP，且 ping 不是浏览器的步骤；\"先发 TCP 三次握手到 80 端口\"顺序错了，握手的前提是已有 IP","【答案】先向 DNS 查询域名对应的 IP 地址（B）"],"pitfalls":["以为先 TCP 握手：没有 IP 无从握手","把 ping 当成浏览器步骤","跳过 DNS 直接说\"连服务器\"","以为 DNS 只在浏览器启动时做：每次访问新域名都要解析"]});

